import { FINE_DAILY_RATE, DUE_DATE_DAYS } from './constants';

export function calculateDueDate(issueDate = new Date()) {
  const due = new Date(issueDate);
  due.setDate(due.getDate() + DUE_DATE_DAYS);
  return due;
}

export function isOverdue(dueDate) {
  return new Date() > new Date(dueDate);
}

export function daysOverdue(dueDate) {
  const now = new Date();
  const due = new Date(dueDate);
  if (now <= due) return 0;
  return Math.floor((now - due) / (1000 * 60 * 60 * 24));
}

export function calculateFine(dueDate) {
  return daysOverdue(dueDate) * FINE_DAILY_RATE;
}

export function formatDate(date) {
  return new Date(date).toLocaleDateString('en-US', {
    year: 'numeric', month: 'short', day: 'numeric',
  });
}
